    const self = this;
    return new Promise((resolve, reject) => {
      let tries = 0;
      const attempt = () => {
        __orig.call(self, player).then((r) => {
          if (r && r.canceled && r.cancelationReason === "UserBusy" && tries++ < 30) system9.runTimeout(attempt, 6);
